   [30]={next_id=31, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="被一语戳中心态，星钻脸颊微微发烫，下意识别过脑袋，刻意维持自己高傲的姿态，嘴硬反驳。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 1, "3503", 0, 0, -2, 153},{ 3, "3503_2", 0, 0, 11, 194.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 1,0},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
