   [152]={next_id=153, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="今天的事，处理得不太好。", msg_color="", msg_size=0, talker="凯瑞总裁", audio="", img="arts/ui/bg/story/storybg_207.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7217", 0, 0, -53.5, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
